import type { Vec3 } from '../contracts/math';

export const ZERO_VEC3: Vec3 = { x: 0, y: 0, z: 0 };

export function vec3(x = 0, y = 0, z = 0): Vec3 {
  return { x, y, z };
}

export function cloneVec3(v: Vec3): Vec3 {
  return { x: v.x, y: v.y, z: v.z };
}

export function addVec3(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x + b.x, y: a.y + b.y, z: a.z + b.z };
}

export function subVec3(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z };
}

export function scaleVec3(v: Vec3, scalar: number): Vec3 {
  return { x: v.x * scalar, y: v.y * scalar, z: v.z * scalar };
}

export function dotVec3(a: Vec3, b: Vec3): number {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

export function lengthVec3(v: Vec3): number {
  return Math.hypot(v.x, v.y, v.z);
}

export function distanceVec3(a: Vec3, b: Vec3): number {
  return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
}

/** Returns null for zero length or non finite vectors so callers can bail out early. */
export function normalizeVec3(v: Vec3): Vec3 | null {
  const length = lengthVec3(v);
  if (!Number.isFinite(length) || length < 1e-8) return null;
  return { x: v.x / length, y: v.y / length, z: v.z / length };
}

/** Right handed rotation around the Y axis, matching the Three.js convention. */
export function rotateAroundY(v: Vec3, radians: number): Vec3 {
  if (!radians) return cloneVec3(v);
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  return { x: v.x * cos + v.z * sin, y: v.y, z: -v.x * sin + v.z * cos };
}
