import type { Vec3 } from '../contracts/math';
import { clamp } from '../physics/helpers';
import { addVec3, lengthVec3, rotateAroundY, scaleVec3, subVec3 } from './vec';

export interface BoxZone {
  shape: 'box';
  center: Vec3;
  halfExtents: Vec3;
  /** yaw in radians, 0 keeps the box axis aligned */
  rotationY?: number;
}

export interface SphereZone {
  shape: 'sphere';
  center: Vec3;
  radius: number;
}

export interface CylinderZone {
  shape: 'cylinder';
  center: Vec3;
  radius: number;
  halfHeight: number;
}

export type ZoneShape = BoxZone | SphereZone | CylinderZone;

/** World point expressed in zone local space, rotation removed for oriented boxes. */
export function toZoneLocal(zone: ZoneShape, point: Vec3): Vec3 {
  const offset = subVec3(point, zone.center);
  if (zone.shape === 'box' && zone.rotationY) return rotateAroundY(offset, -zone.rotationY);
  return offset;
}

export function zoneContains(zone: ZoneShape, point: Vec3, margin = 0): boolean {
  const local = toZoneLocal(zone, point);
  if (zone.shape === 'box') {
    return (
      Math.abs(local.x) <= zone.halfExtents.x + margin &&
      Math.abs(local.y) <= zone.halfExtents.y + margin &&
      Math.abs(local.z) <= zone.halfExtents.z + margin
    );
  }
  if (zone.shape === 'sphere') return lengthVec3(local) <= zone.radius + margin;
  return Math.hypot(local.x, local.z) <= zone.radius + margin && Math.abs(local.y) <= zone.halfHeight + margin;
}

/** 1 in the middle of the volume, 0 on its border, so a fan fades out towards the edge. */
export function zoneFalloff(zone: ZoneShape, point: Vec3): number {
  const local = toZoneLocal(zone, point);
  if (zone.shape === 'box') {
    const ratio = Math.max(
      axisRatio(local.x, zone.halfExtents.x),
      axisRatio(local.y, zone.halfExtents.y),
      axisRatio(local.z, zone.halfExtents.z),
    );
    return clamp(1 - ratio, 0, 1);
  }
  if (zone.shape === 'sphere') return clamp(1 - axisRatio(lengthVec3(local), zone.radius), 0, 1);
  const radial = axisRatio(Math.hypot(local.x, local.z), zone.radius);
  return clamp(1 - Math.max(radial, axisRatio(local.y, zone.halfHeight)), 0, 1);
}

/** Nearest point inside the volume, used to keep a teleporter exit clear of walls. */
export function clampToZone(zone: ZoneShape, point: Vec3): Vec3 {
  const local = clampLocal(zone, toZoneLocal(zone, point));
  const oriented = zone.shape === 'box' && zone.rotationY ? rotateAroundY(local, zone.rotationY) : local;
  return addVec3(zone.center, oriented);
}

function clampLocal(zone: ZoneShape, local: Vec3): Vec3 {
  if (zone.shape === 'box') {
    return {
      x: clamp(local.x, -zone.halfExtents.x, zone.halfExtents.x),
      y: clamp(local.y, -zone.halfExtents.y, zone.halfExtents.y),
      z: clamp(local.z, -zone.halfExtents.z, zone.halfExtents.z),
    };
  }
  if (zone.shape === 'sphere') {
    const length = lengthVec3(local);
    if (length <= zone.radius || length < 1e-8) return local;
    return scaleVec3(local, zone.radius / length);
  }
  const radial = Math.hypot(local.x, local.z);
  const scale = radial <= zone.radius || radial < 1e-8 ? 1 : zone.radius / radial;
  return { x: local.x * scale, y: clamp(local.y, -zone.halfHeight, zone.halfHeight), z: local.z * scale };
}

function axisRatio(value: number, half: number): number {
  if (!Number.isFinite(half) || half <= 1e-8) return Math.abs(value) <= 1e-8 ? 0 : 1;
  return Math.abs(value) / half;
}
